-- Generated by CLI before its telemetry request was rejected. No telemetry is needed to apply SQL.
-- Financial start receipts remain server-side; gameplay/results never enter these RPCs.
begin;
create function public.bud_live_host_local_content(p_host uuid,p_event uuid) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare e bud_platform.live_events; c bud_platform.content_versions;
begin
 select * into e from bud_platform.live_events where id=p_event and host_id=p_host;
 if not found then raise exception 'BUD_EVENT_NOT_FOUND'; end if;
 if e.phase='completed' or e.started_at+interval '4 hours'<=clock_timestamp() then raise exception 'BUD_EVENT_CLOSED'; end if;
 if exists(select 1 from bud_platform.user_restrictions where host_id=p_host and suspended) then raise exception 'BUD_ACCOUNT_RESTRICTED'; end if;
 select * into c from bud_platform.content_versions where id=e.content_version;
 if not found or c.eligible_pairs is null then raise exception 'BUD_CONTENT_NOT_READY'; end if;
 return jsonb_build_object('ownerId',p_host,'eventId',e.id,'title',e.title,'expiresAt',e.started_at+interval '4 hours',
  'content',jsonb_build_object('version',c.id,'pairs',c.eligible_pairs,
   'questions',(select jsonb_agg(item->>'ar' order by n) from jsonb_array_elements(c.questions) with ordinality q(item,n)),
   'conditions',(select jsonb_agg(item->>'ar' order by n) from jsonb_array_elements(c.conditions) with ordinality q(item,n))),
  'legacy',case when e.state->>'storage' is distinct from 'browser-v1' then bud_platform.live_host_event(e.id) else null end);
end;
$$;
create function public.bud_live_host_local_adopt(p_host uuid,p_event uuid) returns jsonb
language plpgsql security invoker set search_path='' as $$
begin
 -- Mark legacy snapshots only after the browser reports its local copy saved.
 -- Historical server snapshots are preserved, never used as a restore fallback afterwards.
 update bud_platform.live_events set state=state||'{"storage":"browser-v1"}'::jsonb where id=p_event and host_id=p_host;
 if not found then raise exception 'BUD_EVENT_NOT_FOUND'; end if;
 return jsonb_build_object('adopted',true);
end;
$$;
create function public.bud_live_host_local_finish(p_host uuid,p_event uuid) returns jsonb
language plpgsql security invoker set search_path='' as $$
begin
 update bud_platform.live_events set phase='completed',updated_at=clock_timestamp(),version=version+1
 where id=p_event and host_id=p_host and state->>'storage'='browser-v1' and phase<>'completed';
 if not exists(select 1 from bud_platform.live_events where id=p_event and host_id=p_host and state->>'storage'='browser-v1') then raise exception 'BUD_EVENT_NOT_FOUND'; end if;
 return jsonb_build_object('closed',true);
end;
$$;
revoke all on function public.bud_live_host_local_content(uuid,uuid),public.bud_live_host_local_adopt(uuid,uuid),public.bud_live_host_local_finish(uuid,uuid) from public,anon,authenticated;
grant execute on function public.bud_live_host_local_content(uuid,uuid),public.bud_live_host_local_adopt(uuid,uuid),public.bud_live_host_local_finish(uuid,uuid) to service_role;
commit;
